questionvariables.text:
plist: [["VA","BC",12,10,11,"VAD",["AVD","VAB","VAC","VAD"]],["VA","CD",15,14,17,"VAB",["VAC","VAB","VAD","AVB"]],["VB","AD",19,11,16,"VBC",["VBA","VBC","VBD","BVC"]],["VB","CD",12,17,17,"VBA",["AVB","VBC","VBD","VBA"]],["VC","AB",24,13,19,"VCD",["CVD","VCD","VCB","VCA"]],["VC","AD",11,17,15,"VCB",["VCD","VCA","BVC","VCB"]],["VD","AB",14,18,25,"VDC",["VDB","CVD","VDC","VDA"]],["VD","BC",9,15,11,"VDA",["VDB","VDA","AVD","VDC"]],["VA","BC",10,20,28,"VAD",["AVD","VAD","VAB","VAC"]],["VC","AB",9,17,21,"VCD",["VCA","VCD","VCB","CVD"]]];
/* Design: angle between skew lines in a pyramid with a rectangular base (slide a base edge so it meets a sloping edge). cc is the base corner of L1, par the base edge through cc parallel to L2, face the isosceles face V-cc-ee. Options: the right angle, the angle with the other base edge at cc, an angle at V, the angle with the base diagonal. Source: adapted from SMP Book 5 (Metric), Chapter 13, 2.5 (Fig. 8(b)). */
ix: 1+rand(10); PP: plist[ix];
L1: PP[1]; L2: PP[2]; ll: PP[3]; ww: PP[4]; se: PP[5]; nm: PP[6]; OP: PP[7];
hh: sqrt(se^2 - (ll^2+ww^2)/4);
LS: "ABCDVOMN"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[ll/2,ww/2,hh],[ll/2,ww/2,0],[ll,ww/2,0],[ll/2,0,0]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
opp(c) := charat("CDAB", ssearch(c, "ABCD"));
cc: charat(nm,2); ee: charat(nm,3); par: sconcat(cc,ee); face: sconcat("V",cc,ee);
oth: first(sublist(["A","B","C","D"], lambda([t], is(t # cc and t # ee and t # opp(cc)))));
oedge: sconcat(cc,oth); side: sqrt(sq(par)); other: sqrt(sq(oedge)); half: nf(side/2);
th: angd(nm); dg1: angd(sconcat("V",cc,oth)); dg2: if side < se then float(acos(side/se)*180/%pi) else NA; cp: 90-th;
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = nm), o], o, OP);
oA: first(sublist(OP, lambda([o], is(charat(o,2) = "V"))));
oD: first(sublist(OP, lambda([o], is(charat(o,2) # "V" and charat(o,3) = opp(cc)))));
oE: first(sublist(OP, lambda([o], is(o # nm and charat(o,2) # "V" and charat(o,3) # opp(cc)))));
